python3 -c "import json,re,yaml; R=json.loads('\n'.join(open('.agent/evidence/104/ci-positive-run.txt').read().splitlines()[1:-1])); t=open('.agent/evidence/104/ci-positive-log.txt').read().splitlines(); m=re.fullmatch(r'gh run view --job ([0-9]+) --log',t[0]); assert m, t[0]; J=[(k,j.get('name') or k) for k,j in yaml.safe_load(open('.github/workflows/compliance.yml'))['jobs'].items() if any('tools/test_convergent_review.py' in (s.get('run') or '') for s in j['steps'])]; jb=[j for j in R['jobs'] if str(j.get('databaseId'))==m.group(1)]; assert len(J)==1 and len(jb)==1 and jb[0]['name']==J[0][1], (J,jb); b='\n'.join(t); assert t[-1]=='EXIT:0' and 'CONFORMANCE: FULL' in b and 'UNSUPPORTED' not in b and 'skipped' not in b and not re.search(r'\b(FAIL|ERROR): test_',b), t[-1]"
